            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "De mens zal eraan moeten wennen te leven in een wereld zonder vrijheid, goedheid en waarheid. Het zal binnenkort op de lagere school worden onderwezen! Deze oorlog is nog maar een voorproefje van de wereld die komt!", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Wat is wetenschap? Wetenschap is de titanische poging van het menselijk intellect zich uit zijn kosmische isolement te verlossen door te begrijpen.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Als je het mij vraagt zijn er drie belangrijke stadia in de geschiedenis van de mens.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "De filosofie onderhoudt, in tegenstelling tot wat de vakfilosofen denken (en wat de theologen staande houden over de godsdienst) geen intiemere relatie met de waarheid dan de poëzie, terwijl ze dikwijls veel lelijker is.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Een aforisme is zoiets als het muziekstukje van een muzikale clown, dat na een paar maten al verstomt.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Ik ben er over het algemeen niet op uit om de regels van de spelling te overtreden. Maar in gevallen waarin deze regels imbeciel zijn en door ongeletterden van het type Camiel Hamans bedacht, is er geen andere oplossing dan er je schouders over ophalen.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Niets lukt zijn personages. Maar hun worsteling is zo troostrijk.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Hoe meer hij over mij zegt, hoe meer het hem zal opvallen hoe zeer ik over hem zwijg.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Als schrijvers hun thema’s gaan begrijpen, gaan ze slechte boeken schrijven. Dat zie je in het latere werk van Hermans. Dan is hij niet meer met verhalen bezig, maar met thema’s. Zijn personages worden themakoelies, dat is het ergste wat een schrijver kan overkomen.", Author = "Willem Frederik Hermans" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Willem_Frederik_Hermans", Text = "Die grote zelfkritiek, de nietsontziende eerlijkheid van zijn werk, is niet de kleine rancune van een geblindeerde gelovige, het is de wrok van Achilles.", Author = "Willem Frederik Hermans" },
